# Let me write a function to compute optimal shifts for each component

def compute_component_shifts(grid, grid_width):
    """
    Compute optimal shifts for each connected component.
    Returns: component_id -> shift
    """
    rows, cols = len(grid), len(grid[0])

    # Get all components
    visited = [[False]*cols for _ in range(rows)]
    comp_list = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                cells = []
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if not visited[cr][cc]:
                        visited[cr][cc] = True
                        cells.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == grid[cr][cc] and not visited[nr][nc]:
                                queue.append((nr, nc))
                comp_list.append(cells)

    if not comp_list:
        return {}

    # Compute optimal shifts
    # Process component by component, ensuring no overlaps

    # First, compute for each row what columns are already taken
    # by components, tracking which component is there

    shifts = {}
    # For each row, track (column, component_id) of all non-zeros
    row_occupants = {r: {} for r in range(rows)}

    # Greedy approach: process components in order of their leftmost column
    # For each component, try the maximum shift that doesn't cause overlap

    # Sort components by their minimum column (sorted by position)
    comp_idx_sorted = sorted(range(len(comp_list)), key=lambda idx: min(c for r,c in comp_list[idx]))

    for comp_idx in comp_idx_sorted:
        cells = comp_list[comp_idx]

        # What shift should this component use?
        # Constraints: for each row this component occupies, no overlap with already-placed components

        # Collect occupied columns by component (if last component placed in row)
        forbidden = {}  # row -> set of columns occupied by components already processed

        for comp_idx2 in comp_idx_sorted:
            if comp_idx2 == comp_idx:
                continue
            shift2 = shifts.get(comp_idx2, 0)
            shift2_cells = [(r, c + shift2) for r, c in comp_list[comp_idx2]]
            for r, c in shift2_cells:
                if r not in forbidden:
                    forbidden[r] = set()
                forbidden[r].add(c)

        # Now try shifts for this component
        # Shift should be as large as possible, no overlap with row_occupants
        rightmost = max(c for r, c in cells)
        max_shift = grid_width - 1 - rightmost

        # For simplicity, let's also allow shifting less than max to avoid overlaps
        for shift in range(max_shift, -1, -1):
            shifted_cells = [(r, c + shift) for r, c in cells]
            valid = True
            for r, c in shifted_cells:
                if r in forbidden and c in forbidden[r]:
                    valid = False
                    break
            if valid:
                shifts[comp_idx] = shift
                break

        # If we couldn't find a valid shift, use 0
        if comp_idx not in shifts:
            shifts[comp_idx] = 0

    return shifts

